)
update public.kp_products p set data=p.data || a.patch
from approved a where p.id=a.id and p.data is distinct from (p.data || a.patch);
commit;
select id, data->>'sku' as sku, data->>'price' as precio, data->'packs' as packs
from public.kp_products where data->>'category'='cerveza' order by sort_order,id;
